647	    E::Settings Variant(Source source, Schedule schedule, Pattern pattern, std::uint32_t landmarks = 48u)
648	    {
649	        return {.Policy = CPD::EStepPolicy::Nystrom, .Threads = 2u, .NystromLandmarks = landmarks, .NystromErrorLimit = 1.0,
650	                .NystromSource = source, .NystromSchedule = schedule, .NystromPattern = pattern};
651	    }
652	
653	    std::vector<glm::dvec3> Landmarks(const E::Evaluator& evaluator)
654	    {
655	        const auto l = evaluator.NystromLandmarks();
656	        std::vector<glm::dvec3> out;
657	        for (std::size_t k = 0; k < l.Size(); ++k) out.push_back({l.X[k], l.Y[k], l.Z[k]});
658	        return out;
659	    }
