661	    std::vector<glm::vec3> Shifted(std::vector<glm::vec3> points, glm::vec3 offset)
662	    {
663	        for (auto& p : points) p += offset;
664	        return points;
665	    }
666	
667	    bool InPaddedBox(const glm::dvec3& p, const std::vector<glm::vec3>& points, double pad)
668	    {
669	        glm::dvec3 lo(1e300), hi(-1e300);
670	        for (const auto& q : points) { lo = glm::min(lo, glm::dvec3(q)); hi = glm::max(hi, glm::dvec3(q)); }
671	        return glm::all(glm::greaterThanEqual(p, lo - pad)) && glm::all(glm::lessThanEqual(p, hi + pad));
