675	TEST(CoherentPointDriftAccelerated, NystromCanRetryAfterTheSourceMovesCloser)
676	{
677	    const auto targetPoints = Cloud(1200, 81), sourcePoints = Cloud(1000, 82);
678	    const Soa target(targetPoints), moved(sourcePoints), separated(Shifted(sourcePoints, {1000.0f, 0.0f, 0.0f}));
679	    constexpr double logOutlier = -std::numeric_limits<double>::infinity();
680	    E::Evaluator dense;
681	    dense.SetTarget(target.View());
682	    E::Sums exact;
683	    ASSERT_TRUE(dense.Evaluate(moved.View(), 4.0, logOutlier, {.Policy = CPD::EStepPolicy::Dense}, exact));
684	    for (const auto schedule : {Schedule::Mixed, Schedule::Fixed, Schedule::Resampled})
685	    {
686	        SCOPED_TRACE(int(schedule));
687	        auto settings = Variant(Source::Points, schedule, Pattern::Random);
688	        settings.NystromErrorLimit = 1e-3;
689	        E::Evaluator reused, fresh;
690	        reused.SetTarget(target.View());
691	        fresh.SetTarget(target.View());
692	        E::Sums rejected, recovered, control;
693	        // At this separation all cross-kernel terms underflow; the shifted exact path still works.
694	        ASSERT_TRUE(reused.Evaluate(separated.View(), 8.0, logOutlier, settings, rejected));
695	        ASSERT_NE(rejected.Used, CPD::EStepPolicy::Nystrom);
696	        ASSERT_FALSE(Landmarks(reused).empty()) << "the first approximation must actually be attempted";
697	        ASSERT_TRUE(fresh.Evaluate(moved.View(), 4.0, logOutlier, settings, control));
698	        ASSERT_EQ(control.Used, CPD::EStepPolicy::Nystrom);
699	        ASSERT_TRUE(reused.Evaluate(moved.View(), 4.0, logOutlier, settings, recovered));
700	        ASSERT_EQ(recovered.Used, CPD::EStepPolicy::Nystrom);
701	        EXPECT_LT(recovered.SampledError, settings.NystromErrorLimit / 10.0);
702	        for (std::size_t i = 0; i < exact.P1.size(); ++i)
703	        {
704	            EXPECT_NEAR(recovered.P1[i], exact.P1[i], 1e-3);
