707	            EXPECT_NEAR(recovered.PXz[i], exact.PXz[i], 1e-3);
708	        }
709	        for (std::size_t j = 0; j < exact.Pt1.size(); ++j)
710	            EXPECT_NEAR(recovered.Pt1[j], exact.Pt1[j], 1e-3);
711	        if (schedule == Schedule::Mixed)
712	        {
713	            EXPECT_EQ(recovered.P1, control.P1);
714	            EXPECT_EQ(recovered.PXx, control.PXx);
